// The feedback session's look (FEEDBACK.md, "UX"): the note pin beside a picked element (NoteBubble: a text field with a mic inside it),
// the slim bar and the chip with its review (optional, for hosts with no chat). Everything they show and do is the headless
// `createFeedbackSession` from `@hachej/boring-feedback/ui` (hover labels, pins, steps, the draft and Send come from there, through the
// privacy policy); this file is how it looks. `useComposerFeedback` adapts a session to the chat composer's optional `feedback` prop
// (registry/pi-chat): ONE annotate toggle and a count chip, structurally, so neither item imports the other.
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { createPortal } from 'react-dom';
import { MicIcon, SquareIcon, XIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Toggle } from '@/components/ui/toggle';
import { Badge } from '@/components/ui/badge';
import { Card } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { readableElement } from '@hachej/boring-feedback/format';
import { createVoiceCapture, type VoiceCapture } from '@hachej/boring-feedback/page';
import { pinMark, type FeedbackSession, type FeedbackSessionSnapshot, type SessionNote } from '@hachej/boring-feedback/ui';
import { useHoldToRecord } from '../pi-chat-voice/use-hold-to-record';
import { useExternal } from './use-external';
import { plainElement, withLabels, type FeedbackLabels } from './feedback-labels';

const plural = (count: number, one: string, many: string): string => `${count} ${count === 1 ? one : many}`;
/** Notes the chip and the bar count: every note that says something (not a pin still being typed), plus the general note. */
export function noteCount(state: FeedbackSessionSnapshot): number {
  return state.notes.filter(note => note.text.trim()).length + (state.general.trim() ? 1 : 0);
}

export interface FeedbackBarProps {
  readonly session: FeedbackSession;
  readonly className?: string;
  /** Docked under the chat composer (the composer's `feedback.bar`) instead of floating at the top of the page. */
  readonly docked?: boolean;
}

/** Pins dropped while recording that have no note yet (nothing transcribed for them, or transcription failed). */
export function emptyPinCount(state: FeedbackSessionSnapshot): number {
  return state.notes.filter(note => note.recorded && !note.text.trim()).length;
}

/** `mm:ss` since `since` (ms), for the recording timer. */
export function elapsed(ms: number): string {
  const seconds = Math.max(0, Math.floor(ms / 1000));
  return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}`;
}

/** The running time of a recording, from when the bar saw it start; 00:00 when not recording. */
function useRecordingTime(recording: boolean): string {
  const [since, setSince] = useState<number | undefined>(undefined);
  const [, tick] = useState(0);
  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect -- the start time is taken when the bar sees the recording start (after commit), once per change of recording
    if (!recording) { setSince(undefined); return; }
    setSince(Date.now());
    const timer = setInterval(() => tick(value => value + 1), 500);
    return () => clearInterval(timer);
  }, [recording]);
  // eslint-disable-next-line react-hooks/purity -- a running clock: each tick re-renders to read the current time
  return elapsed(since === undefined ? 0 : Date.now() - since);
}

function barHint(state: FeedbackSessionSnapshot): string {
  if (state.phase === 'processing') return state.transcribing ? 'Transcribing…' : 'Preparing your feedback…';
  if (state.problem) return state.problem;
  if (state.voice.kind === 'starting') return 'Allow the microphone if your browser asks…';
  if (state.voice.kind === 'recording') return state.using ? 'Recording — using the app' : 'Recording — point and talk';
  return state.using ? 'Using the app: your clicks are recorded as steps' : 'Click what you want to comment on';
}

/**
 * Feedback mode's bar: `● Feedback · N notes · 🎙 Record · Use app · Done · ✕`. While recording: a red dot, the
 * running time, "Recording — point and talk" and Stop. A refused microphone is said in the bar itself, never only in a tooltip.
 */
export function FeedbackBar({ session, className, docked = false }: FeedbackBarProps) {
  const state = useExternal(session);
  const recording = state.voice.kind === 'recording';
  const time = useRecordingTime(recording && (state.phase === 'active' || state.phase === 'processing'));
  if (state.phase !== 'active' && state.phase !== 'processing') return null;
  const processing = state.phase === 'processing';
  const pins = emptyPinCount(state);
  const voiceProblem = state.voice.kind === 'refused' ? state.voice : undefined;
  return <Card size="sm" data-boring="feedback" data-feedback-ignore="" role="toolbar" aria-label="Feedback mode" data-testid="feedback-bar" data-docked={docked ? 'true' : 'false'}
    data-using={state.using ? 'true' : 'false'} data-recording={recording ? 'true' : 'false'} data-transcribing={state.transcribing ? 'true' : 'false'}
    className={['boring-feedback-bar', className].filter(Boolean).join(' ')}
    onKeyDown={event => { if (event.key === 'Escape' && state.bubble) { event.stopPropagation(); session.cancelBubble(); } }}>
    <span className="boring-feedback-bar-title">Feedback</span>
    <span className="boring-feedback-bar-meta" data-testid="feedback-bar-count">{plural(noteCount(state), 'note', 'notes')}{pins ? ` · ${plural(pins, 'pin', 'pins')}` : ''}</span>
    {state.voiceAvailable && <Toggle data-testid="feedback-voice" pressed={recording}
      disabled={processing || state.voice.kind === 'starting' || state.voice.kind === 'stopping'} title={recording ? 'Stop recording' : 'Record your voice while you point: each click drops a pin, what you say becomes its note'}
      onPressedChange={() => { void session.toggleVoice(); }}>
      {recording ? <><SquareIcon data-icon="inline-start" aria-hidden="true" />Stop</> : <><MicIcon data-icon="inline-start" aria-hidden="true" />{state.voice.kind === 'starting' ? 'Starting…' : state.voice.kind === 'stopping' ? 'Stopping…' : 'Record'}</>}
    </Toggle>}
    {recording && <Badge variant="destructive" role="status" data-testid="feedback-recording">
      <span className="boring-feedback-timer" data-testid="feedback-recording-time">{time}</span></Badge>}
    <span className="boring-feedback-hint" role="status" aria-live="polite" data-testid="feedback-bar-hint">{barHint(state)}</span>
    {voiceProblem && <span className="boring-feedback-voice-problem" role="alert" data-testid="feedback-voice-problem" data-code={voiceProblem.code}>{voiceProblem.reason}</span>}
    {!processing && <Toggle data-testid="feedback-use-app" pressed={state.useToggle} onPressedChange={pressed => session.setUseToggle(pressed)}>Use app</Toggle>}
    <Button variant="default" data-testid="feedback-done" disabled={processing} onClick={() => { void session.done(); }}>Done</Button>
    <Button variant="ghost" size="icon" data-testid="feedback-discard" aria-label="Discard feedback" title="Discard feedback" disabled={processing} onClick={() => session.discard()}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>
  </Card>;
}

const BUBBLE_WIDTH = 280;
/** Pixels at the bottom of the viewport taken by comment mode's banner on a phone (CommentBanner, `data-feedback-point-bar="bottom"`), plus a gap; 0 without it. */
export function pointBarInset(document: Document): number {
  const bar = document.querySelector('[data-feedback-point-bar="bottom"]');
  const height = document.defaultView?.innerHeight ?? 768;
  return bar ? Math.max(0, height - bar.getBoundingClientRect().top + 8) : 0;
}

/**
 * Beside the element: below it when the bubble (`size`, its measured height once drawn) fits above point mode's bar (if any), else
 * above it, else as low as it fits. Every branch is clamped to the space above the bar, so the bubble never covers it; a bubble taller
 * than that space scrolls inside it.
 */
function bubblePlace(element: Element, size = 120): CSSProperties {
  const view = element.ownerDocument.defaultView;
  const width = view?.innerWidth ?? 1024, height = (view?.innerHeight ?? 768) - pointBarInset(element.ownerDocument);
  const rect = element.getBoundingClientRect();
  const left = Math.min(Math.max(8, rect.left), Math.max(8, width - BUBBLE_WIDTH - 8));
  const below = rect.bottom + 8;
  const above = rect.top - size - 8;
  const lowest = Math.max(8, height - size);
  const top = Math.min(below + size <= height ? below : above >= 8 ? above : lowest, lowest);
  return { position: 'fixed', top, left, width: Math.min(BUBBLE_WIDTH, width - 16), maxHeight: Math.max(0, height - top), overflowY: 'auto', boxSizing: 'border-box' };
}

/** The bubble's natural height (its content plus borders), not the height it is clamped to, so it grows back when there is room. */
const naturalHeight = (node: HTMLElement | null): number | undefined => (node ? node.scrollHeight + node.offsetHeight - node.clientHeight : 0) || undefined;

type PinVoice = 'idle' | 'starting' | 'recording' | 'transcribing';

/**
 * The mic inside the pin's field, held like the chat's voice message (`useHoldToRecord`, the same gesture policy as the composer and the
 * shell): press and hold to talk (Space or Enter from the keyboard), release and the transcript is added to the note and the note is kept
 * (with `useSendEachNote`, sent at once). A slide off the button, Escape or a hidden page drops the recording. A refused microphone, nothing
 * heard or a rejected transcription is said under the field and never touches the typed text. One capture (`createVoiceCapture`) per pin.
 */
function PinMic({ session, transcribe, words }: { readonly session: FeedbackSession; readonly transcribe: PinTranscribe; readonly words: FeedbackLabels }) {
  const [phase, setPhase] = useState<PinVoice>('idle');
  const [problem, setProblem] = useState<string | undefined>(undefined);
  const capture = useRef<VoiceCapture | null>(null);
  const run = useRef(0);
  const work = useRef<AbortController | null>(null);
  // Let go before the microphone was ready: the recording ends as soon as it starts.
  const released = useRef(false);
  capture.current ??= createVoiceCapture();
  // A closed pin releases the microphone and drops a transcription still in flight.
  useEffect(() => () => { run.current += 1; capture.current?.cancel(); work.current?.abort(); }, []);
  const finish = async (): Promise<void> => {
    const attempt = run.current;
    setPhase('transcribing');
    const recording = await capture.current!.stop().catch(() => null);
    if (attempt !== run.current) return;
    if (!recording) { setPhase('idle'); setProblem(words.voiceNothing); return; }
    const abort = new AbortController();
    work.current = abort;
    try {
      const spoken = (await transcribe(recording.audio, abort.signal)).trim();
      if (attempt !== run.current) return;
      if (!spoken) { setProblem(words.voiceNothing); return; }
      // Appended to what is typed NOW (the person may have kept typing), never replacing it.
      const typed = session.getSnapshot().bubble?.text ?? '';
      session.setBubbleText(`${typed}${typed === '' || /\s$/.test(typed) ? '' : ' '}${spoken}`);
      session.saveBubble();
    } catch { if (attempt === run.current) setProblem(words.voiceFailed); }
    finally { if (work.current === abort) work.current = null; if (attempt === run.current) setPhase('idle'); }
  };
  const hold = useHoldToRecord({
    // Called straight from the press, so the browser ties the permission prompt to the person's gesture.
    start: () => {
      const attempt = ++run.current;
      released.current = false;
      setProblem(undefined); setPhase('starting');
      void capture.current!.start().then(result => {
        if (attempt !== run.current) return;
        if (result.kind === 'refused') { setPhase('idle'); setProblem(result.reason); return; }
        setPhase('recording');
        if (released.current) void finish();
      });
    },
    finish: () => { if (phase === 'recording') void finish(); else released.current = true; },
    cancel: () => { run.current += 1; capture.current?.cancel(); setPhase('idle'); },
  }, phase === 'transcribing');
  const recording = phase === 'recording';
  return <>
    <Button {...hold} variant="ghost" size="icon" className="boring-feedback-pin-mic min-h-11 min-w-11 touch-none select-none" data-testid="feedback-bubble-mic" data-state={phase}
      aria-pressed={recording || phase === 'starting'} aria-label={recording ? words.voiceStop : words.voiceRecord} title={recording ? words.voiceStop : words.voiceRecord} disabled={phase === 'transcribing'}>
      {phase === 'transcribing' ? <span role="status" aria-label={words.voiceTranscribing}>…</span>
        : recording ? <SquareIcon data-icon="inline-start" aria-hidden="true" /> : <MicIcon data-icon="inline-start" aria-hidden="true" />}
    </Button>
    {problem && <span className="boring-feedback-voice-problem" role="alert" data-testid="feedback-bubble-voice-problem">{problem}</span>}
  </>;
}

/** Turns a recording into text (`signal` aborts when the pin closes); a rejection keeps what was typed. */
export type PinTranscribe = (audio: Blob, signal: AbortSignal) => Promise<string>;

/**
 * The pin beside a picked element: a text field with a mic inside it, "Add note" (Enter) and Cancel (Esc). Enter saves, Shift-Enter for a
 * new line, Esc discards the pin. The element is named in plain words (`plainElement`). On a phone it keeps clear of the comment banner. `transcribe` turns the mic's recording into text; without it there is no mic.
 */
export function NoteBubble({ session, labels, transcribe }: { readonly session: FeedbackSession; readonly labels?: Partial<FeedbackLabels>; readonly transcribe?: PinTranscribe }) {
  const state = useExternal(session);
  const words = withLabels(labels);
  const bubble = state.bubble;
  const field = useRef<HTMLTextAreaElement>(null);
  const [place, setPlace] = useState<CSSProperties | undefined>(undefined);
  const [, redraw] = useState(0);
  const [announce, setAnnounce] = useState('');
  const box = useRef<HTMLDivElement>(null);
  const noteId = bubble?.noteId, element = bubble?.element;
  useLayoutEffect(() => { if (element) setPlace(bubblePlace(element, naturalHeight(box.current))); }, [noteId, element]);
  // Once drawn, place it again with its real height (taller with 44px touch targets and wrapped buttons).
  // eslint-disable-next-line react-hooks/exhaustive-deps -- measures after every commit on purpose (content, labels and voice state change the height); it sets state only when the place moved, so it settles
  useLayoutEffect(() => {
    if (!bubble || !place || !box.current) return;
    const next = bubblePlace(bubble.element, naturalHeight(box.current));
    if (next.top !== place.top || next.left !== place.left) setPlace(next);
  });
  useEffect(() => { if (noteId !== undefined) field.current?.focus({ preventScroll: true }); }, [noteId]);
  useEffect(() => {
    if (!element) return;
    const view = element.ownerDocument.defaultView;
    const follow = () => { setPlace(bubblePlace(element, naturalHeight(box.current))); redraw(value => value + 1); };
    view?.addEventListener('scroll', follow, { capture: true, passive: true });
    view?.addEventListener('resize', follow);
    return () => { view?.removeEventListener('scroll', follow, { capture: true }); view?.removeEventListener('resize', follow); };
  }, [noteId, element]);
  // A polite live region outlives the bubble, so the cancellation is heard even though the dialog is gone.
  const cancel = (): void => { session.cancelSelection(); setAnnounce(words.selectionCancelled); };
  const live = <span data-boring="feedback" data-feedback-ignore="" role="status" aria-live="polite" className="boring-feedback-sr" data-testid="feedback-bubble-announce"
    style={{ position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0 0 0 0)', whiteSpace: 'nowrap' }}>{announce}</span>;
  if (!bubble || state.phase !== 'active') return state.phase === 'active' ? live : null;
  const onKeyDown = (event: KeyboardEvent<HTMLElement>): void => {
    if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing && event.target === field.current) { event.preventDefault(); session.saveBubble(); }
    else if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); session.cancelBubble(); }
  };
  return <>{live}<Card size="sm" data-boring="feedback" data-feedback-ignore="" role="dialog" aria-label={`Note ${bubble.number}`} data-testid="feedback-bubble" data-note={bubble.number}
    ref={box} className="boring-feedback-bubble" style={place} onKeyDown={onKeyDown}>
    <span className="boring-feedback-bubble-head"><span className="boring-feedback-pin" aria-hidden="true">{pinMark(bubble.number)}</span>
      <span className="boring-feedback-bubble-label" data-testid="feedback-bubble-label">{plainElement(bubble.label, words)}</span></span>
    <span className="boring-feedback-pin-field">
      <Textarea ref={field} data-testid="feedback-bubble-input" rows={2} placeholder={words.bubblePlaceholder} aria-label={words.bubblePlaceholder} value={bubble.text}
        onChange={event => session.setBubbleText(event.target.value)} />
      {transcribe && <PinMic key={bubble.noteId} session={session} transcribe={transcribe} words={words} />}
    </span>
    <span className="boring-feedback-bubble-actions">
      <Button variant="ghost" className="min-h-11 min-w-11" data-testid="feedback-cancel-selection" onClick={cancel}>{words.cancelSelection}</Button>
      <Button variant="default" className="min-h-11 min-w-11" data-testid="feedback-bubble-save" onClick={() => session.saveBubble()}>{words.add}</Button>
    </span>
  </Card></>;
}

export interface FeedbackChipProps {
  readonly session: FeedbackSession;
  /** Opens the review on first render (journeys). */
  readonly defaultOpen?: boolean;
  /** Offer Copy report in the review: the way to use feedback with no chat and no store. */
  readonly copy?: boolean;
}

/** The one composer chip after Done: `💬 Feedback · 3 notes · /settings/:section`. Click opens the review; × discards. */
export function FeedbackChip({ session, defaultOpen = false, copy = false }: FeedbackChipProps) {
  const state = useExternal(session);
  const [open, setOpen] = useState(defaultOpen);
  const chip = useRef<HTMLSpanElement>(null);
  if (state.phase !== 'review') return null;
  const count = noteCount(state);
  const pins = emptyPinCount(state);
  const refusal = state.send.kind !== 'idle' && state.send.kind !== 'sending' && state.send.kind !== 'saved' ? state.send.reason : undefined;
  return <span ref={chip} data-boring="feedback" data-feedback-ignore="" data-testid="feedback-chip" data-send={state.send.kind} className="boring-feedback-chip">
    <Button variant="outline" className="min-w-0 max-w-full" data-testid="feedback-chip-open" aria-expanded={open} onClick={() => setOpen(value => !value)}
      title={refusal ?? 'Review your feedback before sending'}>
      <span aria-hidden="true">💬</span> Feedback · {plural(count, 'note', 'notes')}{pins ? ` · ${plural(pins, 'pin', 'pins')} to describe` : ''} · <span className="boring-feedback-chip-route">{state.route}</span>
    </Button>
    <Button variant="ghost" size="icon-sm" data-testid="feedback-chip-discard" aria-label="Discard feedback" title="Discard feedback" onClick={() => { session.highlight(undefined); session.discard(); }}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>
    {state.problem && <span className="boring-feedback-warning" role="alert" data-testid="feedback-chip-voice">{state.problem}</span>}
    {refusal && <span className="boring-feedback-warning" role="alert" data-testid="feedback-chip-problem">{refusal}</span>}
    {/* In the page's body: the chip may sit in a transformed chat bar, where a fixed panel would not be placed against the viewport. */}
    {/* eslint-disable-next-line react-hooks/refs -- the chip element is read when the review opens (after a click, so it is attached); reading it does not drive a re-render */}
    {open && createPortal(<FeedbackReview session={session} anchor={chip.current} copy={copy} onClose={() => setOpen(false)} />, chip.current?.ownerDocument.body ?? document.body)}
  </span>;
}

function reviewPlace(anchor: Element | null): CSSProperties | undefined {
  if (!anchor) return undefined;
  const view = anchor.ownerDocument.defaultView;
  const width = view?.innerWidth ?? 1024, height = view?.innerHeight ?? 768;
  const rect = anchor.getBoundingClientRect();
  const panel = Math.min(416, width - 24);
  return { position: 'fixed', left: Math.min(Math.max(12, rect.left), width - panel - 12), bottom: Math.max(12, height - rect.top + 8), width: panel };
}

/** The compact review: notes in order, editable and removable; hovering a note highlights its element in the page, or says it is not here. */
export function FeedbackReview({ session, anchor = null, copy = false, onClose }: { readonly session: FeedbackSession; readonly anchor?: Element | null; readonly copy?: boolean; readonly onClose: () => void }) {
  const state = useExternal(session);
  const [where, setWhere] = useState<Readonly<Record<number, 'shown' | 'not-on-page'>>>({});
  const [place, setPlace] = useState<CSSProperties | undefined>(undefined);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- the place is measured from the anchor's layout, which exists only after commit; set before paint, once per anchor
  useLayoutEffect(() => { setPlace(reviewPlace(anchor)); }, [anchor]);
  useEffect(() => () => { session.highlight(undefined); }, [session]);
  const hover = (id: number | undefined): void => {
    const result = session.highlight(id);
    if (id !== undefined && result !== 'none') setWhere(value => ({ ...value, [id]: result }));
  };
  const onKeyDown = (event: KeyboardEvent<HTMLElement>): void => { if (event.key === 'Escape') { event.stopPropagation(); onClose(); } };
  return <Card size="sm" data-boring="feedback" data-feedback-ignore="" role="dialog" aria-label="Review feedback" data-testid="feedback-review" className="boring-feedback-review"
    style={place} onKeyDown={onKeyDown} onMouseLeave={() => hover(undefined)}>
    <header className="boring-feedback-sheet-header"><h2>Feedback · {state.route}</h2>
      <Button variant="ghost" size="icon" aria-label="Close review" title="Close review" data-testid="feedback-review-close" onClick={onClose}><XIcon data-icon="inline-start" aria-hidden="true" /></Button></header>
    {state.problem && <p className="boring-feedback-warning" role="alert" data-testid="feedback-review-problem">{state.problem}</p>}
    <ol className="boring-feedback-notes">
      {state.notes.map(note => <li key={note.id} data-testid="feedback-review-note" data-note={note.number} data-where={where[note.id]}
        onMouseEnter={() => hover(note.id)} onFocus={() => hover(note.id)}>
        <span className="boring-feedback-note-head"><span className="boring-feedback-pin" aria-hidden="true">{pinMark(note.number)}</span>
          <ElementName note={note} />
          {note.from === 'voice' && <Badge variant="secondary" data-testid="feedback-review-voice">voice</Badge>}
          {where[note.id] === 'not-on-page' && <Badge variant="secondary" data-testid="feedback-review-elsewhere">not on this page</Badge>}
          <Button variant="ghost" size="icon" aria-label={`Remove note ${note.number}`} title={`Remove note ${note.number}`} data-testid="feedback-review-remove" onClick={() => session.removeNote(note.id)}><XIcon data-icon="inline-start" aria-hidden="true" /></Button></span>
        <Textarea rows={2} aria-label={`Note ${note.number}`} data-testid="feedback-review-text" value={note.text} placeholder={note.recorded ? 'Nothing was said here: type a note, or remove the pin' : undefined}
          onChange={event => session.setNoteText(note.id, event.target.value)} />
      </li>)}
    </ol>
    <label className="boring-feedback-field"><span>General note</span>
      <Textarea rows={2} data-testid="feedback-review-general" placeholder="Anything else? (optional)" value={state.general} onChange={event => session.setGeneral(event.target.value)} /></label>
    <p className="boring-feedback-meta">{state.stepCount > 1 ? `${plural(state.stepCount, 'step', 'steps')} recorded between the notes. ` : ''}{copy ? 'Copy the report and paste it anywhere.' : 'Sent with your next message.'}</p>
    {copy && <div className="boring-feedback-actions">
      <Button variant="default" data-testid="feedback-copy" onClick={() => { void session.copy(); }}>Copy report</Button></div>}
    {copy && <p role="status" aria-live="polite" className="boring-feedback-status" data-testid="feedback-status" data-copy={state.copy.kind}>
      {state.copy.kind === 'copied' ? 'Report copied. Paste it anywhere.' : state.copy.kind === 'manual' ? 'The clipboard is not available here: select the report below and copy it.' : state.copy.kind === 'refused' ? state.copy.reason : ''}</p>}
    {copy && state.copy.kind === 'manual' && <Textarea readOnly className="boring-feedback-manual" data-testid="feedback-manual-copy" value={state.copy.text} rows={6} onFocus={event => event.currentTarget.select()} />}
    {copy && state.copy.kind === 'copied' && <details className="boring-feedback-copied"><summary>Copied report</summary><pre data-testid="feedback-copy-text">{state.copy.text}</pre></details>}
  </Card>;
}

/**
 * A note's element as one calm line: the readable name (semibold) and the file basename (muted, monospace), the full path in the
 * tooltip. The same reading as the pi-chat feedback card's element line (`readableElement` from `@hachej/boring-feedback/format`).
 */
export function ElementName({ note }: { readonly note: SessionNote }) {
  const readable = note.fallback ? readableElement(note.fallback, note.source) : { name: note.label };
  return <span className="boring-feedback-element" data-testid="feedback-review-element" title={'path' in readable && readable.path ? readable.path : note.label}>
    <span className="boring-feedback-element-name" data-testid="feedback-review-name">{readable.name}</span>
    {'file' in readable && readable.file && <span className="boring-feedback-element-file" data-testid="feedback-review-file">{readable.file}</span>}
  </span>;
}

/** What `useComposerFeedback` returns: the structural shape of pi-chat's `ComposerFeedback`. */
export interface ComposerFeedbackProp {
  readonly annotate: () => void;
  readonly active: boolean;
  readonly count: number;
  readonly clear: () => void;
  readonly attach: (text: string) => Promise<{ readonly kind: 'ok'; readonly text: string } | { readonly kind: 'refused'; readonly reason: string }>;
  readonly sent: () => void;
}

/** A Markdown fence longer than any backtick run in the text. */
function fenced(text: string): string {
  const longest = Math.max(0, ...[...text.matchAll(/`+/g)].map(match => match[0].length));
  const fence = '`'.repeat(Math.max(3, longest + 1));
  return `${fence}markdown\n${text.endsWith('\n') ? text : `${text}\n`}${fence}`;
}

/** Touch or a compact screen: the panel covers the app and there is no hover, so annotating is point mode (use the app, then point). */
function pointsInstead(): boolean {
  return globalThis.matchMedia?.('(pointer: coarse)').matches === true || (globalThis.innerWidth ?? 1024) < 768;
}

/**
 * Starts (or resumes) annotating in either mode, with Esc as a way out. The session swallows Esc on the page (it only closes a pin), so
 * this listens on the window's capture phase BEFORE the session starts, and ends the mode (Done: the notes wait for Send) when no pin is
 * open. From the review, `resume` keeps the notes, anchors and save guards: a second round adds to the same draft.
 */
function startAnnotating(session: FeedbackSession, mode: 'point' | undefined = pointsInstead() ? 'point' : undefined, fresh = true): void {
  if (fresh) sentInRound.delete(session);
  const view = globalThis.window;
  const onKey = (event: globalThis.KeyboardEvent): void => {
    // Esc that ends annotating is spent: a host layer around the composer (a panel that closes on Esc) must not also react to it.
    if (event.key === 'Escape' && !session.getSnapshot().bubble) { event.preventDefault(); event.stopPropagation(); void session.done(); }
  };
  view?.addEventListener('keydown', onKey, { capture: true });
  session.resume(mode ? { mode } : {});
  const stop = session.subscribe(() => {
    if (session.getSnapshot().phase === 'active') return;
    view?.removeEventListener('keydown', onKey, { capture: true });
    stop();
  });
}

/**
 * The composer's `feedback` prop for a session: ONE annotate toggle (targeting with a hover highlight; point mode on touch and compact
 * screens, and again after Esc to add more), a count of the notes taken, and Send attaching them: a saved report as its `@` mention (the host's mention resolver inlines
 * the stored report with the person's access), otherwise the rendered report inline in a fenced block. Pair it with `NoteBubble`.
 */
export function useComposerFeedback(session: FeedbackSession | undefined): ComposerFeedbackProp | undefined {
  const state = useSyncState(session);
  if (!session || !state) return undefined;
  const open = state.phase === 'active' || state.phase === 'processing';
  return {
    annotate: () => {
      const phase = session.getSnapshot().phase;
      if (phase === 'active') void session.done();
      else if (phase === 'idle' || phase === 'review') startAnnotating(session);
    },
    active: open,
    // A note being typed in the pin counts: Send saves it.
    count: noteCount(state) + (state.bubble?.fresh && state.bubble.text.trim() ? 1 : 0),
    clear: () => { session.highlight(undefined); session.discard(); },
    attach: async text => {
      // Send while annotating ends it first: the pin being typed is kept.
      if (session.getSnapshot().phase === 'active') await session.done();
      const attached = await session.attach();
      if (attached.kind === 'refused') return attached;
      const body = attached.kind === 'mention' ? `@${attached.path}` : fenced(attached.text);
      return { kind: 'ok', text: text.trim() ? `${text.trimEnd()}\n\n${body}` : body };
    },
    sent: () => session.sent(),
  };
}

/** Notes sent one by one in the current round of comment mode (`useSendEachNote`), for the banner; a new round starts at zero. */
const sentInRound = new WeakMap<FeedbackSession, number>();
export const notesSent = (session: FeedbackSession): number => sentInRound.get(session) ?? 0;

/**
 * Each note goes to the chat the moment it is added: its element and text as one message (`send`, the chat's follow-up send), and
 * comment mode stays on for the next note. Nothing waits in a hidden batch, and the agent's reply follows in the conversation. Without
 * `send`, the notes wait for the person's next message as before. A refused report or a failed send stays in the review, where the composer shows it.
 */
export function useSendEachNote(session: FeedbackSession | undefined, send: ((text: string) => Promise<unknown>) | undefined): void {
  const state = useSyncState(session);
  const busy = useRef(false);
  useEffect(() => {
    if (!session || !send || !state || busy.current) return;
    if (state.phase !== 'active' || state.bubble || !state.notes.some(note => note.text.trim())) return;
    busy.current = true;
    const mode = state.mode === 'point' ? 'point' : undefined;
    void (async () => {
      let again = false;
      try {
        await session.done();
        const attached = await session.attach();
        if (attached.kind === 'refused') return;
        const submission = await send(attached.kind === 'mention' ? `@${attached.path}` : fenced(attached.text)).catch(() => undefined);
        if (submission === false || submission === undefined || submission === null) return;
        sentInRound.set(session, notesSent(session) + noteCount(session.getSnapshot()));
        session.sent();
        again = true;
      } finally {
        busy.current = false;
        if (again) startAnnotating(session, mode, false);
      }
    })();
  }, [session, send, state]);
}

const NO_STATE = { getSnapshot: () => undefined, subscribe: () => () => {} };
function useSyncState(session: FeedbackSession | undefined): FeedbackSessionSnapshot | undefined {
  return useExternal<FeedbackSessionSnapshot | undefined>(session ?? NO_STATE);
}

/** What `usePointComments` returns: the structural shape of the maquette viewer's `MaquetteComments` (any viewer may take it). */
export interface PointCommentsProp {
  /** A host-owned proxy element for an opaque frame pick, checked by the session's root and privacy policy. */
  readonly pick: (element: Element) => void;
  readonly reposition: () => void;
  /** Clicks are currently captured, false during Use app or processing. */
  readonly picking: boolean;
  /** The session is annotating now (point mode or feedback mode). */
  readonly active: boolean;
  /** Point mode on the page, keeping the notes already taken (from the review too); Done when it is on. Esc ends it like the composer's toggle. */
  readonly point: () => void;
  /** Every pin with a marked element: its number and the `data-feedback-id` it sits in (`SessionNote.feedbackId`). */
  readonly pins: readonly { readonly number: number; readonly target: string }[];
}

/**
 * Comment pins for a viewer inside the page (the maquette viewer's `comments`): the same session, notes, bubble, review and Send as the
 * composer's toggle, entered in point mode from the viewer's own icon. A viewer marks its parts with `data-feedback-id` and matches the
 * pins on them. Undefined without a session, so the viewer shows no icon.
 */
export function usePointComments(session: FeedbackSession | undefined): PointCommentsProp | undefined {
  const state = useSyncState(session);
  // One object per session state, so a host that puts it in a memoized kind list re-renders only when the pins or the mode change.
  return useMemo(() => !session || !state ? undefined : {
    active: state.phase === 'active' || state.phase === 'processing',
    pick: session.pick,
    reposition: session.reposition,
    picking: state.phase === 'active' && !state.using,
    point: () => {
      const phase = session.getSnapshot().phase;
      if (phase === 'active') void session.done();
      else if (phase === 'idle' || phase === 'review') startAnnotating(session, 'point');
    },
    pins: state.notes.flatMap(note => note.feedbackId ? [{ number: note.number, target: note.feedbackId }] : []),
  }, [session, state]);
}

// PointButton: enters pick mode on the application root. Picking itself (events captured and stopped, keys, touch, labels) is
// `createPicker` from `@hachej/boring-feedback/page`; this file is the button and the hint people see while they point.
import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from 'react';
import { createPicker, type Picker, type PickerOverlay, type PickerState, type PrivacyPolicy } from '@hachej/boring-feedback/page';
import { Toggle } from '@/components/ui/toggle';

export interface PointButtonProps {
  /** The application root; only elements inside it can be picked. */
  readonly root: () => Element | null;
  readonly policy: PrivacyPolicy;
  /** The page's shared overlay (`usePickerOverlay`). */
  readonly overlay: PickerOverlay | undefined;
  /** Called with the pinned elements; the overlay still shows them. */
  readonly onPinned: (elements: readonly Element[]) => void;
  readonly onCancel?: () => void;
  /** Shift-click pins several elements. Default true. */
  readonly multiple?: boolean;
  readonly children?: ReactNode;
  readonly className?: string;
}

export function PointButton({ root, policy, overlay, onPinned, onCancel, multiple = true, children = 'Point', className }: PointButtonProps) {
  const picker = useRef<Picker | null>(null);
  const [state, setState] = useState<PickerState | null>(null);
  const callbacks = useRef({ onPinned, onCancel });
  useLayoutEffect(() => { callbacks.current = { onPinned, onCancel }; });
  useEffect(() => () => { picker.current?.dispose(); picker.current = null; }, []);

  const picking = state?.mode === 'picking';
  const toggle = (): void => {
    if (picking) { picker.current?.cancel(); return; }
    const element = root();
    if (!element || !overlay) return;
    picker.current?.dispose();
    const created = createPicker({ root: element, policy, overlay, multiple, onChange: setState });
    picker.current = created;
    void created.start().then(result => {
      if (result.kind === 'pinned') callbacks.current.onPinned(result.elements);
      else callbacks.current.onCancel?.();
    });
  };

  return <span data-boring="feedback" data-feedback-ignore="" className={['boring-feedback-point', className].filter(Boolean).join(' ')}>
    <Toggle data-testid="feedback-point" pressed={picking} disabled={!overlay} onPressedChange={toggle}>
      {picking ? 'Cancel' : children}
    </Toggle>
    {picking && <span role="status" aria-live="polite" data-testid="feedback-point-hint" className="boring-feedback-hint">
      {state?.label ?? state?.refusal ?? 'Point at an element'}
      <span className="boring-feedback-keys"> · Click to pin{multiple ? ', Shift-click for several' : ''} · ↑ parent ↓ child · Esc</span>
    </span>}
  </span>;
}

// PickerOverlay: styles only. The overlay itself (its shadow root, pointer-events: none, and what it draws) is `createOverlay` from
// `@hachej/boring-feedback/page`; this file is the editable look, passed into that shadow root. Labels come from the privacy policy there, so
// restyling cannot change what they say. The host keeps one overlay per page and shares it between PointButton and FeedbackReport.
import { useEffect, useState } from 'react';
import { createOverlay, type PickerOverlay } from '@hachej/boring-feedback/page';

/** CSS added to the overlay's shadow root, over its base styles: fonts, sizes, weights, corners and elevation read the app's
 * tokens only; tones (hover, pinned, reveal, candidate) keep the base styles' borders. Parts: `box`, `label`, `toolbar` (and `box-<tone>`, `label-<tone>` for hover, pinned,
 * reveal and candidate). The hover and pinned labels are the policy's technical names (`button · masked`): hidden, the note bubble names the element in plain words. The colors read the host's `--boring-feedback-*` variables, which inherit through the shadow boundary. */
export const pickerOverlayStyles = `
.box { border-radius: var(--radius-sm, calc(var(--radius, 0.625rem) * 0.6)); }
.label { border-radius: var(--radius-sm, calc(var(--radius, 0.625rem) * 0.6)); box-shadow: var(--shadow-sm, none); font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif); font-size: var(--text-xs, 0.75rem); font-weight: var(--font-weight-medium, 500); line-height: var(--leading-normal, 1.5); }
.label[data-tone="candidate"] { font-weight: var(--font-weight-bold, 700); }
.label[data-tone="hover"], .label[data-tone="pinned"] { display: none; }
.toolbar { border-radius: var(--radius-xl, calc(var(--radius, 0.625rem) * 1.4)); box-shadow: var(--shadow-lg, none); }
.toolbar button { border-radius: var(--radius-md, calc(var(--radius, 0.625rem) * 0.8)); font-family: var(--font-sans, ui-sans-serif, system-ui, sans-serif); font-size: var(--text-sm, 0.875rem); font-weight: var(--font-weight-semibold, 600); line-height: var(--leading-tight, 1.25); }
`;

/** One overlay for the page, created after mount and removed on unmount. */
export function usePickerOverlay(styles: string = pickerOverlayStyles): PickerOverlay | undefined {
  const [overlay, setOverlay] = useState<PickerOverlay>();
  useEffect(() => {
    const created = createOverlay({ document, styles });
    // eslint-disable-next-line react-hooks/set-state-in-effect -- the overlay is a DOM resource created after mount (and disposed on unmount); its handle has to reach render.
    setOverlay(created);
    return () => { created.dispose(); };
  }, [styles]);
  return overlay;
}

// AnnotateSheet: the note, Cancel selection (back to a general note, nothing attached), Copy report and, when the host has a save endpoint, Save. The draft, its anchors and the Save operation id are
// the headless `createAnnotation` from `@hachej/boring-feedback/ui`; this file is how the sheet looks and what it says.
import { useEffect, useLayoutEffect, useRef, useState, type CSSProperties, type KeyboardEvent } from 'react';
import { protectionNotice, type Annotation, type CopyState, type FeedbackProtection, type SaveState } from '@hachej/boring-feedback/ui';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Textarea } from '@/components/ui/textarea';
import { XIcon } from 'lucide-react';
import { useExternal } from './use-external';
import { withLabels, type FeedbackLabels } from './feedback-labels';

export interface AnnotateSheetProps {
  readonly annotation: Annotation;
  readonly onClose: () => void;
  /** The pinned element the sheet opens beside. Without it the sheet docks at the bottom. */
  readonly near?: Element;
  /** The store's declared protection, when the host saves. An unprotected store is stated. */
  readonly protection?: FeedbackProtection;
  readonly title?: string;
  /** Words of the controls (`feedbackLabelsFr` for French); what is left out keeps the English default. */
  readonly labels?: Partial<FeedbackLabels>;
  /**
   * Called after the selection was cancelled (Esc, the Cancel selection button, or clicking the selected element again). The host
   * returns to the picker or to no zone here, typically by closing the sheet. Without it the sheet stays open as a general note, with
   * what was typed kept.
   */
  readonly onCancelSelection?: () => void;
}

const copyMessage = (copy: CopyState): string => {
  switch (copy.kind) {
    case 'copied': return 'Report copied. Paste it anywhere.';
    case 'manual': return 'The clipboard is not available here: select the report below and copy it.';
    case 'refused': return copy.reason;
    default: return '';
  }
};
const saveMessage = (save: SaveState): string => {
  switch (save.kind) {
    case 'saving': return 'Saving…';
    case 'saved': return 'Saved.';
    case 'unknown': return `${save.reason} Nothing is lost: Save again uses the same operation, so it cannot be stored twice.`;
    case 'denied': return `Not saved: ${save.reason}`;
    case 'unavailable': return `Not saved: ${save.reason}`;
    case 'conflict': return `Not saved: ${save.reason}`;
    case 'invalid': return save.reason;
    default: return '';
  }
};

const SHEET_WIDTH = 360;
function placeNear(element: Element | undefined): CSSProperties | undefined {
  if (!element || !element.isConnected) return undefined;
  const view = element.ownerDocument.defaultView;
  if (!view || view.innerWidth < 640) return undefined;
  const rect = element.getBoundingClientRect();
  const right = rect.right + 12;
  const left = right + SHEET_WIDTH <= view.innerWidth - 12 ? right : Math.max(12, rect.left - SHEET_WIDTH - 12);
  const top = Math.min(Math.max(12, rect.top), Math.max(12, view.innerHeight - 420));
  return { position: 'fixed', top, left, width: SHEET_WIDTH };
}

export function AnnotateSheet({ annotation, onClose, near, protection, title, labels, onCancelSelection }: AnnotateSheetProps) {
  const state = useExternal(annotation);
  const words = withLabels(labels);
  const heading = state.selected ? (title ?? words.title) : words.askGeneral;
  const note = useRef<HTMLTextAreaElement>(null);
  const [place, setPlace] = useState<CSSProperties | undefined>(undefined);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- placed from the page's layout after commit and before paint, once per anchor
  useLayoutEffect(() => { setPlace(placeNear(near)); }, [near]);
  const [cancelled, setCancelled] = useState(false);
  const callbacks = useRef({ onCancelSelection });
  useLayoutEffect(() => { callbacks.current = { onCancelSelection }; });
  useEffect(() => { note.current?.focus({ preventScroll: true }); }, []);
  // Focus goes back to where it was when the sheet opened (the Point button, after the picker restored it), not to the top of the page.
  useEffect(() => {
    const opener = note.current?.ownerDocument.activeElement;
    const before = opener && opener !== note.current ? opener : undefined;
    return () => { if (before && before.isConnected && typeof (before as HTMLElement).focus === 'function') (before as HTMLElement).focus({ preventScroll: true }); };
  }, []);
  const cancelSelection = (): void => {
    if (!annotation.clearSelection()) return;
    setCancelled(true);
    note.current?.focus({ preventScroll: true });
    callbacks.current.onCancelSelection?.();
  };
  // Clicking the selected element again cancels the selection instead of activating it.
  const selected = state.selected;
  useEffect(() => {
    const view = near?.ownerDocument.defaultView;
    if (!near || !view || !selected) return;
    const onClick = (event: Event): void => {
      const path = event.composedPath();
      if (path.some(item => (item as Element).hasAttribute?.('data-feedback-ignore')) || !path.includes(near)) return;
      event.preventDefault(); event.stopPropagation();
      if (annotation.clearSelection()) { setCancelled(true); note.current?.focus({ preventScroll: true }); callbacks.current.onCancelSelection?.(); }
    };
    view.addEventListener('click', onClick, { capture: true });
    return () => view.removeEventListener('click', onClick, { capture: true });
  }, [near, selected, annotation]);
  const notice = protection ? protectionNotice(protection) : undefined;
  // Esc cancels the selection first (one step back: to no zone); on a general note it closes the sheet.
  const onKeyDown = (event: KeyboardEvent<HTMLElement>): void => {
    if (event.key !== 'Escape') return;
    event.stopPropagation();
    if (state.selected && state.save.kind !== 'saved' && state.save.kind !== 'saving') cancelSelection(); else onClose();
  };
  const copyText = state.copy.kind === 'copied' || state.copy.kind === 'manual' ? state.copy.text : undefined;
  const saved = state.save.kind === 'saved';

  return <Card data-boring="feedback" data-feedback-ignore="" role="dialog" aria-label={heading} data-testid="feedback-sheet" data-selected={state.selected ? 'true' : 'false'}
    className="boring-feedback-sheet" data-docked={place ? undefined : 'bottom'} style={place} onKeyDown={onKeyDown}>
    <header className="boring-feedback-sheet-header">
      <h2>{heading}</h2>
      <Button variant="ghost" size="icon" aria-label={words.close} title={words.close} data-testid="feedback-close" onClick={onClose}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>
    </header>
    {state.selected && <ul className="boring-feedback-targets" data-testid="feedback-targets">
      {state.targets.map((target, index) => <li key={index}>{target}</li>)}
    </ul>}
    {state.refused.length > 0 && <p role="alert" className="boring-feedback-warning" data-testid="feedback-refused">
      {state.refused.length === 1 ? 'One element could not be pointed at' : `${state.refused.length} elements could not be pointed at`}: {state.refused.map(item => item.reason).join('; ')}.
    </p>}
    <label className="boring-feedback-field">
      <span>{state.selected ? words.changeField : words.generalField}</span>
      <Textarea ref={note} data-testid="feedback-note" rows={4} value={state.said} readOnly={saved} onChange={event => annotation.setSaid(event.target.value)} />
    </label>
    <div className="boring-feedback-actions">
      {state.selected && state.save.kind !== 'saved' && <Button variant="ghost" data-testid="feedback-cancel-selection" disabled={state.save.kind === 'saving'}
        onClick={cancelSelection}>{words.cancelSelection}</Button>}
      <Button variant="ghost" data-testid="feedback-copy" onClick={() => { void annotation.copy(); }}>{words.copyReport}</Button>
      {state.canSave && <Button variant="default" data-testid="feedback-save" disabled={state.save.kind === 'saving' || saved}
        onClick={() => { void annotation.save(); }}>{state.save.kind === 'unknown' ? words.saveAgain : saved ? words.saved : words.save}</Button>}
    </div>
    <p role="status" aria-live="polite" className="boring-feedback-status" data-testid="feedback-status" data-copy={state.copy.kind} data-save={state.save.kind}>
      {[copyMessage(state.copy), saveMessage(state.save), cancelled && !state.selected ? words.selectionCancelled : ''].filter(Boolean).join(' ')}
    </p>
    {state.copy.kind === 'manual' && copyText !== undefined && <Textarea readOnly className="boring-feedback-manual" data-testid="feedback-manual-copy" value={copyText}
      onFocus={event => event.currentTarget.select()} rows={6} />}
    {state.copy.kind === 'copied' && copyText !== undefined && <details className="boring-feedback-copied"><summary>Copied report</summary>
      <pre data-testid="feedback-copy-text">{copyText}</pre></details>}
    {notice && <p className="boring-feedback-notice" data-testid="feedback-protection">{notice}</p>}
  </Card>;
}

// FeedbackList: stored feedback, newest first, as the host's authorized list route returns it. Rows are `listRows` from
// `@hachej/boring-feedback/ui`; an unprotected store is stated above them.
import type { FeedbackListItem } from '@hachej/boring-feedback/format';
import { listRows, protectionNotice, type FeedbackProtection } from '@hachej/boring-feedback/ui';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';

export interface FeedbackListProps {
  readonly items: readonly FeedbackListItem[];
  readonly protection: FeedbackProtection;
  readonly onOpen: (id: string) => void;
  /** The open item, highlighted. */
  readonly activeId?: string;
  /** Why the list could not be loaded (denied, unavailable). */
  readonly problem?: string;
  readonly now?: Date;
}

export function FeedbackList({ items, protection, onOpen, activeId, problem, now }: FeedbackListProps) {
  const notice = protectionNotice(protection);
  const rows = listRows(items, now);
  return <Card size="sm" role="region" data-boring="feedback" data-feedback-ignore="" className="boring-feedback-list" aria-label="Feedback" data-testid="feedback-list">
    {notice && <p className="boring-feedback-notice" data-testid="feedback-protection">{notice}</p>}
    {problem !== undefined && <p role="alert" className="boring-feedback-warning">{problem}</p>}
    {problem === undefined && rows.length === 0 && <p className="boring-feedback-empty">No feedback yet. Point at something to leave some.</p>}
    <ul>
      {rows.map(row => <li key={row.id}>
        <Button variant="ghost" className="h-auto w-full flex-col items-start" data-testid="feedback-item" data-id={row.id} aria-current={row.id === activeId ? 'true' : undefined} onClick={() => onOpen(row.id)}>
          <span className="boring-feedback-title">{row.title}</span>
          <span className="boring-feedback-meta"><span data-status={row.status}>{row.status}</span> · {row.where} · {row.age}</span>
        </Button>
      </li>)}
    </ul>
  </Card>;
}

// FeedbackReport: one stored report and Show. Show resolves each anchor against the live page now (`showAnchor` from
// `@hachej/boring-feedback/ui`): exact and moved placements are revealed on the overlay, ambiguous ones are numbered for the person to choose,
// and missing, stale or unsupported results are said as they are. Nothing uncertain is revealed without that choice.
import { useEffect, useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { XIcon } from 'lucide-react';
import type { FeedbackReport as Report } from '@hachej/boring-feedback/format';
import type { PickerOverlay, PrivacyPolicy } from '@hachej/boring-feedback/page';
import { reportView, showAnchor, type ShowOutcome } from '@hachej/boring-feedback/ui';

export interface FeedbackReportProps {
  readonly report: Report;
  /** Show works only in the application page itself: pass its root, policy and overlay. Without them Show is not offered. */
  readonly page?: { readonly root: () => Element | null; readonly policy: PrivacyPolicy; readonly overlay: PickerOverlay | undefined };
  readonly onClose?: () => void;
}

type Shown = { readonly anchor: number; readonly outcome: ShowOutcome | 'working' };

const outcomeText = (outcome: ShowOutcome): string => {
  switch (outcome.kind) {
    case 'revealed': return outcome.placement === 'chosen' ? 'Shown: the element you chose.' : outcome.placement === 'moved' ? 'Shown. It has moved since the feedback was left.' : 'Shown.';
    case 'choose': return `${outcome.candidates.length} elements could be the one meant. Choose the right one:`;
    case 'stale': return `Not shown: ${outcome.reason}`;
    case 'missing': return `Not shown: ${outcome.reason}`;
    default: return `Not shown: ${outcome.reason}`;
  }
};

export function FeedbackReport({ report, page, onClose }: FeedbackReportProps) {
  const view = reportView(report);
  const [shown, setShown] = useState<Shown | null>(null);
  const overlay = page?.overlay;
  useEffect(() => () => { overlay?.clear(); }, [overlay]);
  // eslint-disable-next-line react-hooks/set-state-in-effect -- another report starts with nothing shown; runs once per report id
  useEffect(() => { setShown(null); overlay?.clear(); }, [report.id]); // eslint-disable-line react-hooks/exhaustive-deps -- clears on a new report only; a new overlay is cleared by the effect above

  const show = async (index: number): Promise<void> => {
    const root = page?.root();
    if (!page || !root) { setShown({ anchor: index, outcome: { kind: 'unsupported', reason: 'Open the application page to see it.' } }); return; }
    setShown({ anchor: index, outcome: 'working' });
    const outcome = await showAnchor({ anchor: report.anchors[index], root, policy: page.policy, ...(page.overlay ? { overlay: page.overlay } : {}), note: view.title });
    setShown({ anchor: index, outcome });
  };
  const choose = (outcome: Extract<ShowOutcome, { kind: 'choose' }>, number: number, index: number): void => setShown({ anchor: index, outcome: outcome.choose(number) });

  return <Card size="sm" role="article" data-boring="feedback" data-feedback-ignore="" className="boring-feedback-report" data-testid="feedback-report" data-id={view.id}>
    <header className="boring-feedback-sheet-header">
      <h2>{view.title}</h2>
      {onClose && <Button variant="ghost" size="icon" aria-label="Close" title="Close" onClick={onClose}><XIcon data-icon="inline-start" aria-hidden="true" /></Button>}
    </header>
    <p className="boring-feedback-meta">
      <span data-status={view.status}>{view.status}</span>
      {view.author !== undefined && <> · {view.author}</>}
      {view.app !== undefined && <> · {view.app} {view.route}</>}
      {view.build !== undefined && <> · build {view.build}</>}
    </p>
    <p className="boring-feedback-said" data-testid="feedback-said">{view.said}</p>
    <ol className="boring-feedback-anchors">
      {view.anchors.map(anchor => {
        const current = shown?.anchor === anchor.index ? shown.outcome : undefined;
        return <li key={anchor.index} data-testid="feedback-anchor">
          <span>{anchor.fallback}</span>
          {anchor.source !== undefined && <code>{anchor.source}</code>}
          {page && anchor.placeable && <Button variant="ghost" data-testid="feedback-show" disabled={current === 'working'} onClick={() => { void show(anchor.index); }}>Show</Button>}
          {!anchor.placeable && <span className="boring-feedback-meta">This page cannot place {anchor.kind}.</span>}
          {current !== undefined && current !== 'working' && <div role="status" className="boring-feedback-status" data-testid="feedback-show-result" data-kind={current.kind}>
            {outcomeText(current)}
            {current.kind === 'choose' && <ol className="boring-feedback-candidates">
              {current.candidates.map(candidate => <li key={candidate.number}>
                <Button variant="outline" data-testid="feedback-candidate" data-number={candidate.number}
                  onClick={() => choose(current, candidate.number, anchor.index)}>{candidate.number} · {candidate.label}</Button>
              </li>)}
            </ol>}
          </div>}
        </li>;
      })}
    </ol>
    {view.widened.length > 0 && <p className="boring-feedback-meta" data-testid="feedback-widened">Privacy policy widened by the app: {view.widened.join(', ')}</p>}
    {view.resolutions.length > 0 && <section className="boring-feedback-resolutions"><h3>Resolution</h3>
      {view.resolutions.map((entry, index) => <p key={index}><strong>{entry.by}</strong> · {entry.note}</p>)}</section>}
  </Card>;
}

// Subscribes a component to one of the headless states of `@hachej/boring-feedback/ui` (annotate, list, report).
import { useSyncExternalStore } from 'react';
import type { ExternalState } from '@hachej/boring-feedback/ui';

export function useExternal<State>(state: ExternalState<State>): State {
  return useSyncExternalStore(state.subscribe, state.getSnapshot, state.getSnapshot);
}

'use client';

import { useRef, useState } from 'react';
import type { ReactNode } from 'react';
// Type-only: pi-chat has no alias for these chat types, so the card names them from the model SDK the host already installs.
import type { ToolCall, ToolResultMessage } from '@earendil-works/pi-ai';
import { FEEDBACK_ID, readableElement } from '@hachej/boring-feedback/format';
import { CheckIcon, LocateFixedIcon, MessageSquareTextIcon, ShieldAlertIcon } from 'lucide-react';
import type { ChatCard } from '../pi-chat/rows';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Item, ItemContent, ItemDescription, ItemHeader, ItemMedia, ItemTitle } from '@/components/ui/item';
import { cn } from '../utils/utils';

/*
 * The feedback card (FEEDBACK.md, "Activating it on an agent" and "UX"): `feedback` tool results in the transcript. A `list`
 * result is a list of reports with their element lines and placements; a `show` result is an OFFER for one element line. The
 * server-side tool never reveals anything: hovering (or focusing) an element line asks the host's page (`onShowFeedback`,
 * AmbientChat mounted in the subject's application page) to resolve it against the live page and highlight it, leaving the
 * line clears it (`onHideFeedback`), and clicking it does the same and lets the person choose among ambiguous candidates. The
 * card displays the host's honest result inline as a small badge (✓ only after the host reported a reveal; "2 matches · choose",
 * "confirm", "not on this page" or one short phrase otherwise, the host's full reason in its tooltip). Without the callback an offer
 * says `unavailable`: open the application page. Element lines read as `«Save profile» button  SettingsPage.jsx:65` (the readable
 * name, then the file basename; the full path in the tooltip). Everything shown is data, rendered as text.
 */
export const FEEDBACK_TOOL = 'feedback';

/** `intent`: a hover only highlights (an ambiguous placement is reported, not chosen); a click may ask the person to choose. */
export interface FeedbackShowRequest { readonly id: string; readonly anchor: number; readonly note?: string; readonly intent?: 'hover' | 'click' }
/**
 * What the host's page did, as a `PresentationResult` without a value. `detail` lets the card say it in a few words: `found`, `moved`
 * or `chosen` for a reveal; `choose` (with `matches`, the number of candidates) when a person must pick one, `missing` when nothing on
 * the page matches, `not-chosen` when the person picked none, `no-page` outside the application page. `reason` stays the full sentence.
 */
export type FeedbackShowDetail = 'found' | 'moved' | 'chosen' | 'choose' | 'missing' | 'not-chosen' | 'no-page';
export type FeedbackShowOutcome =
  | { readonly kind: 'applied'; readonly reason?: string; readonly detail?: FeedbackShowDetail }
  | { readonly kind: 'stale' | 'unavailable' | 'denied'; readonly reason: string; readonly detail?: FeedbackShowDetail; readonly matches?: number };
export interface FeedbackCardConfig {
  /** Resolve and reveal in the live page. Give it only where the chat is mounted in the subject's application page. */
  readonly onShowFeedback?: ((request: FeedbackShowRequest) => Promise<FeedbackShowOutcome>) | undefined;
  /** The pointer or focus left an element line: clear the highlight. */
  readonly onHideFeedback?: (() => void) | undefined;
}

/** `placement` is a short phrase, or undefined when there is nothing to say ("checked in the page": only the person's page can place it). */
export interface FeedbackAnchorView { readonly index: number; readonly kind: string; readonly fallback: string; readonly placement?: string; readonly placementDetail?: string; readonly source?: string }
export interface FeedbackItemView {
  readonly id: string; readonly title: string; readonly status: string; readonly author: string; readonly age: string; readonly subject: string;
  readonly anchors: readonly FeedbackAnchorView[]; readonly unavailable: boolean;
}
export type FeedbackResultView =
  | { readonly kind: 'list'; readonly items: readonly FeedbackItemView[]; readonly unprotected: boolean; readonly more: boolean }
  | { readonly kind: 'offer'; readonly id: string; readonly anchor: number; readonly note?: string; readonly fallback: string }
  | { readonly kind: 'refused'; readonly outcome: string; readonly reason: string };

const isObject = (value: unknown): value is Readonly<Record<string, unknown>> => value !== null && typeof value === 'object' && !Array.isArray(value);
const text = (value: unknown, fallback = ''): string => typeof value === 'string' ? value : fallback;
const MENTION = /(?:^|\/)([^/]+)\.md$/;

/** The report id of an `@<root><id>.md` mention, or undefined. The id is checked by `@hachej/boring-feedback/format`. */
export function feedbackMentionId(path: string): string | undefined {
  const id = MENTION.exec(path)?.[1];
  return id !== undefined && FEEDBACK_ID.test(id) ? id : undefined;
}

const CHECKED_IN_THE_PAGE = 'checked in the page';
/** How a placement reads in the card: a short phrase (what it was evaluated against goes to the tooltip), or nothing to say. */
function placementOf(value: unknown): { readonly placement?: string; readonly placementDetail?: string } {
  if (typeof value === 'string') return value === CHECKED_IN_THE_PAGE ? {} : { placement: value };
  if (!isObject(value)) return { placement: 'not evaluated' };
  const detail = typeof value['evaluated'] === 'string' ? { placementDetail: value['evaluated'] } : {};
  switch (value['kind']) {
    case 'exact': return { placement: 'found', ...detail };
    case 'moved': return { placement: 'moved', ...detail };
    case 'ambiguous': return { placement: 'several matches', ...detail };
    case 'partial': return { placement: 'partly found', ...detail };
    case 'missing': return { placement: 'not found', ...detail };
    case 'unsupported': return { placement: 'unsupported', ...detail };
    default: return { placement: 'not evaluated' };
  }
}

/** The card's view of a `feedback` tool result, or undefined when it has no card (read, resolve, malformed, failed). */
export function feedbackResultView(call: ToolCall, result: ToolResultMessage | undefined): FeedbackResultView | undefined {
  if (call.name !== FEEDBACK_TOOL || !result || result.isError) return undefined;
  const part = result.content.find(item => item.type === 'text');
  let value: unknown;
  try { value = JSON.parse(part?.type === 'text' ? part.text : ''); } catch { return undefined; }
  if (!isObject(value)) return undefined;
  if (value['action'] === 'list' && value['kind'] === 'available' && Array.isArray(value['items'])) {
    const items = value['items'].flatMap((item): FeedbackItemView[] => {
      if (!isObject(item) || typeof item['id'] !== 'string' || !FEEDBACK_ID.test(item['id'])) return [];
      const anchors = Array.isArray(item['anchors']) ? item['anchors'].flatMap((anchor): FeedbackAnchorView[] => isObject(anchor) && Number.isInteger(anchor['index'])
        ? [{ index: anchor['index'] as number, kind: text(anchor['kind']), fallback: text(anchor['fallback'], 'an anchor'), ...placementOf(anchor['placement']),
          ...(isObject(anchor['signals']) && typeof anchor['signals']['source'] === 'string' ? { source: anchor['signals']['source'] } : {}) }] : []) : [];
      return [{ id: item['id'], title: text(item['title'], item['id']), status: text(item['status']), author: text(item['author']), age: text(item['age']), subject: text(item['subject']), anchors, unavailable: item['unavailable'] !== undefined }];
    });
    return { kind: 'list', items, unprotected: value['protection'] === 'unprotected', more: typeof value['cursor'] === 'string' };
  }
  if (value['action'] !== 'show') return undefined;
  if (value['kind'] === 'offered' && typeof value['id'] === 'string' && FEEDBACK_ID.test(value['id']) && Number.isInteger(value['anchor']) && (value['anchor'] as number) >= 0) {
    return { kind: 'offer', id: value['id'], anchor: value['anchor'] as number, fallback: text(value['fallback'], 'the place this feedback points at'), ...(typeof value['note'] === 'string' && value['note'] ? { note: value['note'] } : {}) };
  }
  if (typeof value['kind'] === 'string' && ['denied', 'unsupported', 'missing', 'unavailable'].includes(value['kind'])) return { kind: 'refused', outcome: value['kind'], reason: text(value['reason']) };
  return undefined;
}

const OUTCOME_KINDS = ['applied', 'stale', 'unavailable', 'denied'] as const;
const DETAILS: readonly FeedbackShowDetail[] = ['found', 'moved', 'chosen', 'choose', 'missing', 'not-chosen', 'no-page'];
const NO_PAGE: FeedbackShowOutcome = { kind: 'unavailable', reason: 'Open the application page to see where this feedback points.', detail: 'no-page' };

/**
 * The few words an outcome reads as in the card, from what the host reported (never more): ✓ only for `applied`; candidates to
 * choose from as "2 matches · choose" (one candidate: "confirm"); nothing matching as "not on this page"; otherwise one short phrase.
 */
export function outcomeBadge(outcome: FeedbackShowOutcome): string {
  if (outcome.kind === 'applied') return outcome.detail === 'moved' ? '✓ moved' : outcome.detail === 'chosen' ? '✓ chosen' : '✓';
  if (outcome.kind === 'denied') return 'no access';
  switch (outcome.detail) {
    case 'choose': return outcome.matches === 1 ? 'confirm' : outcome.matches !== undefined && outcome.matches > 1 ? `${outcome.matches} matches · choose` : 'several matches · choose';
    case 'missing': return 'not on this page';
    case 'not-chosen': return 'none chosen';
    case 'no-page': return 'open the app page to see it';
    default: return outcome.kind === 'stale' ? 'changed since' : 'can’t show it here';
  }
}

/** Ask the host page, and keep only an outcome it really reported. A throw or an unknown value is `unavailable`. */
async function askPage(onShow: NonNullable<FeedbackCardConfig['onShowFeedback']>, request: FeedbackShowRequest): Promise<FeedbackShowOutcome> {
  try {
    const outcome: unknown = await onShow(request);
    if (isObject(outcome) && (OUTCOME_KINDS as readonly unknown[]).includes(outcome['kind'])) {
      const reason = text(outcome['reason']);
      const detail = (DETAILS as readonly unknown[]).includes(outcome['detail']) ? { detail: outcome['detail'] as FeedbackShowDetail } : {};
      const matches = Number.isInteger(outcome['matches']) && (outcome['matches'] as number) >= 0 ? { matches: outcome['matches'] as number } : {};
      return outcome['kind'] === 'applied' ? { kind: 'applied', ...(reason ? { reason } : {}), ...detail }
        : { kind: outcome['kind'] as 'stale' | 'unavailable' | 'denied', reason: reason || 'No reason given', ...detail, ...matches };
    }
    return { kind: 'unavailable', reason: 'The page reported no recognised result' };
  } catch { return { kind: 'unavailable', reason: 'The page could not show it' }; }
}

/**
 * One element line: hover or focus highlights it in the page through the host, leaving clears it, click does the same and may let the
 * person choose among candidates. The outcome is stated inline. Without the host callback the line is plain text.
 */
function ElementLine({ request, label, source, onShowFeedback, onHideFeedback, initial, onOutcome, children }: {
  readonly request: Omit<FeedbackShowRequest, 'intent'>; readonly label: string; readonly source?: string | undefined;
  readonly onShowFeedback: FeedbackCardConfig['onShowFeedback']; readonly onHideFeedback: FeedbackCardConfig['onHideFeedback'];
  readonly initial?: FeedbackShowOutcome | undefined; readonly onOutcome?: ((outcome: FeedbackShowOutcome | undefined) => void) | undefined; readonly children?: ReactNode;
}) {
  const [state, setState] = useState<FeedbackShowOutcome | 'showing' | undefined>(initial);
  const asked = useRef(0);
  // A click keeps what it showed (and any choice it asked for) after the pointer or focus leaves, until the next hover; a hover is transient.
  const kept = useRef(false);
  const show = async (intent: 'hover' | 'click') => {
    if (!onShowFeedback) return;
    kept.current = intent === 'click';
    const ask = ++asked.current;
    setState('showing');
    const outcome = await askPage(onShowFeedback, { ...request, intent });
    // A later hover or click wins; an earlier answer never overwrites it.
    if (ask !== asked.current) return;
    setState(outcome);
    onOutcome?.(outcome);
  };
  const hide = () => {
    if (kept.current) return;
    asked.current++; setState(current => current === 'showing' ? undefined : current); onHideFeedback?.();
  };
  const outcome = typeof state === 'object' ? state : undefined;
  const readable = readableElement(label, source);
  const badge = state === 'showing' ? <span data-testid="feedback-outcome" role="status" className="shrink-0 text-xs text-muted-foreground">looking…</span>
    : outcome ? <Badge data-testid="feedback-outcome" role="status" title={outcome.reason ?? 'Shown in the page.'} data-outcome={outcome.kind} variant={outcome.kind === 'applied' ? 'secondary' : 'outline'}>
      {outcome.kind === 'applied' ? <><CheckIcon aria-hidden="true" />{outcomeBadge(outcome).slice(1).trim() || <span className="sr-only">shown in the page</span>}</> : outcomeBadge(outcome)}</Badge>
      : children;
  const text = <span className="flex min-w-0 flex-wrap items-baseline gap-x-1.5">
    <span data-testid="feedback-fallback" className="font-semibold [overflow-wrap:anywhere]">{readable.name}</span>
    {readable.file && <span data-testid="feedback-source" title={readable.path ?? readable.file} className="font-mono text-xs font-normal text-muted-foreground">{readable.file}</span>}
    {badge}</span>;
  return <span className="block" data-outcome={outcome?.kind}>
    {onShowFeedback
      ? <Button variant="ghost" data-testid="feedback-element" data-feedback-id={request.id} data-anchor={request.anchor} title={`${label}${readable.path ? ` · ${readable.path}` : ''}\nHover to see it on the page; click to choose if it matches several places`}
        onMouseEnter={() => { void show('hover'); }} onFocus={() => { void show('hover'); }} onMouseLeave={hide} onBlur={hide} onClick={() => { void show('click'); }}
        className="h-auto w-full justify-start whitespace-normal text-left">{text}</Button>
      : <span data-testid="feedback-element" data-feedback-id={request.id} data-anchor={request.anchor} title={label} className="block">{text}</span>}
  </span>;
}

/** A report title (the person's note): two lines at most, with a toggle to read the rest. */
function ClampedTitle({ text: title }: { readonly text: string }) {
  const [open, setOpen] = useState(false);
  const long = title.length > 110 || title.includes('\n');
  return <span className="block">
    <span data-testid="feedback-title" className={cn('block whitespace-pre-line [overflow-wrap:anywhere]', !open && 'line-clamp-2')}>{title}</span>
    {long && <Button variant="link" size="xs" data-testid="feedback-title-more" aria-expanded={open} onClick={() => setOpen(value => !value)}>{open ? 'less' : 'more'}</Button>}
  </span>;
}

function Offer({ view, onShowFeedback, onHideFeedback }: { readonly view: Extract<FeedbackResultView, { kind: 'offer' }>; readonly onShowFeedback: FeedbackCardConfig['onShowFeedback']; readonly onHideFeedback: FeedbackCardConfig['onHideFeedback'] }) {
  const [outcome, setOutcome] = useState<FeedbackShowOutcome | undefined>(onShowFeedback ? undefined : NO_PAGE);
  return <Item variant="outline" size="sm" render={<section />} data-testid="feedback-card" data-kind="offer" data-feedback-id={view.id} data-outcome={outcome?.kind} aria-label="Feedback offer" className="my-2 max-w-md text-start">
    <ItemMedia variant="icon"><LocateFixedIcon aria-hidden="true" /></ItemMedia>
    <ItemContent className="min-w-0 basis-0">
      <ItemDescription>Feedback {view.id}</ItemDescription>
      <ElementLine request={{ id: view.id, anchor: view.anchor, ...(view.note === undefined ? {} : { note: view.note }) }} label={view.fallback}
        onShowFeedback={onShowFeedback} onHideFeedback={onHideFeedback} initial={onShowFeedback ? undefined : NO_PAGE} onOutcome={next => setOutcome(next)} />
      {view.note && <ItemDescription data-testid="feedback-note" className="line-clamp-none [overflow-wrap:anywhere]">{view.note}</ItemDescription>}
    </ItemContent>
  </Item>;
}

function List({ view, onShowFeedback, onHideFeedback }: { readonly view: Extract<FeedbackResultView, { kind: 'list' }>; readonly onShowFeedback: FeedbackCardConfig['onShowFeedback']; readonly onHideFeedback: FeedbackCardConfig['onHideFeedback'] }) {
  return <Item variant="outline" size="sm" render={<section />} data-testid="feedback-card" data-kind="list" aria-label="Feedback" className="my-2 max-w-xl flex-col items-stretch text-start">
    <ItemHeader>
      <ItemTitle><MessageSquareTextIcon className="size-4" aria-hidden="true" />Feedback · {view.items.length}{view.more ? '+' : ''}</ItemTitle>
      {view.unprotected && <Badge variant="secondary" data-testid="feedback-unprotected"><ShieldAlertIcon aria-hidden="true" />Unprotected store</Badge>}
    </ItemHeader>
    {view.items.length === 0 && <ItemDescription>No feedback.</ItemDescription>}
    <ul className="m-0 flex list-none flex-col gap-1.5 p-0">
      {view.items.map(item => <Item key={item.id} variant="muted" size="xs" render={<li />} data-testid="feedback-item" data-feedback-id={item.id} data-status={item.status}>
        <ItemContent className="min-w-0 basis-0">
          <ClampedTitle text={item.title} />
          <ItemDescription data-testid="feedback-meta" className="line-clamp-none">{[item.status, item.author, item.age, item.unavailable ? 'unavailable' : ''].filter(Boolean).join(' · ')}</ItemDescription>
          {item.anchors.length > 0 && <ul className="m-0 list-none p-0">
            {item.anchors.map(anchor => <li key={anchor.index} data-testid="feedback-anchor" className="[overflow-wrap:anywhere]">
              <ElementLine request={{ id: item.id, anchor: anchor.index }} label={anchor.fallback} source={anchor.source}
                onShowFeedback={anchor.kind === 'app.element@1' ? onShowFeedback : undefined} onHideFeedback={onHideFeedback}>
                {anchor.placement && <Badge variant="outline" data-testid="feedback-placement" title={anchor.placementDetail}>{anchor.placement}</Badge>}
              </ElementLine></li>)}
          </ul>}
        </ItemContent>
      </Item>)}
    </ul>
  </Item>;
}

/** One `feedback` tool result: a list, an offer, or a refusal stated as such. Element lines highlight in the page on hover. */
export function FeedbackCard({ view, onShowFeedback, onHideFeedback }: { readonly view: FeedbackResultView; readonly onShowFeedback?: FeedbackCardConfig['onShowFeedback']; readonly onHideFeedback?: FeedbackCardConfig['onHideFeedback'] }) {
  if (view.kind === 'list') return <List view={view} onShowFeedback={onShowFeedback} onHideFeedback={onHideFeedback} />;
  if (view.kind === 'offer') return <Offer view={view} onShowFeedback={onShowFeedback} onHideFeedback={onHideFeedback} />;
  return <Item variant="muted" size="sm" render={<section />} data-testid="feedback-card" data-kind="refused" data-outcome={view.outcome} aria-label="Feedback" className="my-2 max-w-md text-start">
    <ItemContent className="min-w-0 basis-0"><ItemDescription className="line-clamp-none">Feedback not shown ({view.outcome}){view.reason ? `: ${view.reason}` : ''}</ItemDescription></ItemContent></Item>;
}

/** An `@<root><id>.md` mention of a report in a sent message. */
export function FeedbackMention({ path, id, onOpen }: { readonly path: string; readonly id: string; readonly onOpen?: ((path: string) => void) | undefined }) {
  const body = <><MessageSquareTextIcon aria-hidden="true" />{id}</>;
  return onOpen
    ? <Button variant="outline" size="xs" data-testid="feedback-mention" data-path={path} aria-label={`Open feedback ${id}`} onClick={() => onOpen(path)}>{body}</Button>
    : <Badge variant="outline" data-testid="feedback-mention" data-path={path} title={`Feedback ${id}`}>{body}</Badge>;
}

/**
 * The `mentions.render` of a pi-chat host (`MentionsConfig`): `@<root><id>.md` report mentions in sent messages become feedback chips,
 * any other mention keeps pi-chat's default. `onOpen` (the chat's `mentions.open`) makes a chip a button.
 */
export function feedbackMentionRenderer(onOpen?: ((path: string) => void) | undefined): (path: string) => ReactNode | undefined {
  return path => {
    const id = feedbackMentionId(path);
    return id === undefined ? undefined : <FeedbackMention path={path} id={id} onOpen={onOpen} />;
  };
}

/**
 * A `renderTool` for `PiChat` or `AmbientChat`: cards for `feedback` list results, offers and refusals, `inline` so they
 * stay in the transcript in expert mode. Memoize it; compose with another renderer as `(c, r) => feedback(c, r) ?? mine(c, r)`.
 */
export function feedbackRenderTool(config: FeedbackCardConfig = {}): (call: ToolCall, result: ToolResultMessage | undefined) => ChatCard | undefined {
  return (call, result) => {
    const view = feedbackResultView(call, result);
    return view ? { content: <FeedbackCard view={view} onShowFeedback={config.onShowFeedback} onHideFeedback={config.onHideFeedback} />, inline: true } : undefined;
  };
}

// A microphone button for the composer: records on the first click, stops on the second, transcribes the recording and appends the
// text to the composer draft. It never sends: the person reads the transcript and presses Send. Pass it to `PiChat` as `tools`.
import { useDictation } from '@hachej/boring-ui-kit/chat-react/voice';
import { Loader2Icon, MicIcon, SquareIcon, XIcon } from 'lucide-react';
import type { NativeChatController } from '@hachej/boring-ui-kit/native-chat';
import { appendToDraft } from '@hachej/boring-ui-kit/chat-text';
import { useChatText } from '../pi-chat/labels';
import { Button } from '@/components/ui/button';
import { Toggle } from '@/components/ui/toggle';

export interface VoiceInputProps {
  /** The chat whose composer draft receives the transcript. */
  readonly controller: NativeChatController;
  /** Turns the recording into text. `signal` aborts when the person cancels or leaves the page; a rejection shows an error. */
  readonly transcribe: (audio: Blob, signal: AbortSignal) => Promise<string>;
  /** Capture limit (default five minutes); the person still finishes before text is appended. */
  readonly maxMs?: number | undefined;
}

export function VoiceInput({ controller, transcribe, maxMs }: VoiceInputProps) {
  const { labels } = useChatText();
  const { phase, problem, start, finish, cancel } = useDictation({ transcribe, labels, maxMs, target: controller,
    onText: (spoken, signal) => {
      if (!signal.aborted) controller.setText(appendToDraft(controller.getSnapshot().draft.text, spoken));
    },
  });
  const onClick = () => { if (phase === 'idle') start(); else finish(); };
  const recording = phase === 'recording';
  const busy = phase === 'transcribing';
  return (
    <div className="flex items-center gap-1.5">
      {(phase === 'starting' || recording || busy) && <Button variant="ghost" size="icon" data-testid="composer-voice-cancel" aria-label={labels.voiceCancel} title={labels.voiceCancel} onClick={cancel}>
        <XIcon data-icon="inline-start" aria-hidden="true" /></Button>}
      <Toggle data-testid="composer-voice" data-state={phase} pressed={recording} aria-label={phase === 'starting' ? labels.voiceCancel : recording ? labels.voiceStop : labels.voiceRecord}
        title={phase === 'starting' ? labels.voiceCancel : recording ? labels.voiceStop : labels.voiceRecord} disabled={busy} onPressedChange={onClick}>
        {busy ? <Loader2Icon data-icon="inline-start" className="animate-spin motion-reduce:animate-none" role="status" aria-label={labels.voiceTranscribing} />
          : recording ? <SquareIcon data-icon="inline-start" aria-hidden="true" />
          : <MicIcon data-icon="inline-start" aria-hidden="true" />}
      </Toggle>
      {problem && <span role="alert" data-testid="composer-voice-problem" className="max-w-56 text-xs leading-4 text-destructive">{problem}</span>}
    </div>
  );
}

// The words of the feedback controls that cancel a selection, ask a general question and drive point mode, as data. The defaults are English, like the
// rest of the copied components; `feedbackLabelsFr` is the French set (pass it as `labels` to AnnotateSheet, FeedbackBar,
// NoteBubble and PointMode). A host may pass any subset: what it leaves out keeps the default.
export interface FeedbackLabels {
  /** The annotate sheet's title for a selected zone, and the bubble's accessible name prefix is `note`. */
  readonly title: string;
  readonly close: string;
  /** The button that drops the selected zone and keeps what was typed. */
  readonly cancelSelection: string;
  /** The entry point (bar button, sheet button, general sheet title): a note with no element attached. */
  readonly askGeneral: string;
  /** The sheet's field label for a selected zone / for a general question. */
  readonly changeField: string;
  readonly generalField: string;
  readonly copyReport: string;
  readonly save: string;
  readonly saveAgain: string;
  readonly saving: string;
  readonly saved: string;
  readonly bubblePlaceholder: string;
  /** The pin's field label, its Add button, and the mic inside the field (record, stop, transcribing, nothing heard, failed). */
  readonly add: string;
  readonly voiceRecord: string;
  readonly voiceStop: string;
  readonly voiceTranscribing: string;
  readonly voiceNothing: string;
  readonly voiceFailed: string;
  /** Announced when the selection was cancelled, so a screen reader hears that the zone is gone. */
  readonly selectionCancelled: string;
  /**
   * The comment-mode banner (CommentBanner): its title, the count of notes, the on/off switch's name, what to do while on (a tap on a
   * phone, a click with a mouse), what to do while off (use the app, then switch back on: the notes stay), and Done.
   */
  readonly commentMode: string;
  readonly pointCount: (count: number) => string;
  readonly commentSwitch: string;
  readonly commentTap: string;
  readonly commentClick: string;
  readonly commentPaused: string;
  /** Once notes went to the agent one by one (`useSendEachNote`): how many, and that the reply comes in the conversation. */
  readonly commentSent: (count: number) => string;
  readonly pointDone: string;
  /** The picked element in the note bubble, in plain words: its kind (by ARIA role or tag) and its visible name when it has one. */
  readonly element: (kind: string | undefined, name: string | undefined) => string;
}

/** The roles and tags people can name; anything else is « this element ». */
const KINDS_EN: Record<string, string> = { button: 'Button', link: 'Link', a: 'Link', heading: 'Title', img: 'Image', textbox: 'Field', input: 'Field', checkbox: 'Checkbox',
  combobox: 'List', listbox: 'List', option: 'Choice', tab: 'Tab', row: 'Row', listitem: 'Row', li: 'Row', cell: 'Cell', dialog: 'Window', navigation: 'Menu', menuitem: 'Menu item',
  article: 'Card', region: 'Card', group: 'Card', meter: 'Gauge', progressbar: 'Gauge', list: 'List', paragraph: 'Text', p: 'Text', span: 'Text' };
const KINDS_FR: Record<string, string> = { button: 'Bouton', link: 'Lien', a: 'Lien', heading: 'Titre', img: 'Image', textbox: 'Champ', input: 'Champ', checkbox: 'Case à cocher',
  combobox: 'Liste', listbox: 'Liste', option: 'Choix', tab: 'Onglet', row: 'Ligne', listitem: 'Ligne', li: 'Ligne', cell: 'Cellule', dialog: 'Fenêtre', navigation: 'Menu', menuitem: 'Entrée du menu',
  article: 'Carte', region: 'Carte', group: 'Carte', meter: 'Jauge', progressbar: 'Jauge', list: 'Liste', paragraph: 'Texte', p: 'Texte', span: 'Texte' };
const named = (kinds: Record<string, string>, unknown: string) => (kind: string | undefined, name: string | undefined): string => {
  const word = kind ? kinds[kind] : undefined;
  return name ? `${word ?? unknown} « ${name} »` : word ?? unknown;
};

/**
 * The picker's label (`button «Save»`, `button · masked`, `Form.tsx · link «Help»`, `masked`) in plain words: `Button « Save »`,
 * `Button`, `Link « Help »`, `This element`. Nothing technical (no component, no « masked »): what the policy hides stays hidden.
 */
export function plainElement(label: string, words: Pick<FeedbackLabels, 'element'>): string {
  const match = /(?:^|· )([a-z][a-z0-9-]*)(?: · masked| «(.*)»)$/.exec(label.trim());
  return words.element(match?.[1], match?.[2]?.trim() || undefined);
}

